const { createHash } = require('node:crypto');
const { readFileSync } = require('node:fs');
const path = require('node:path');

/** Content version of the Pagefind bundle (generated by `npm run search:build-index` before `next build`). */
function pagefindVersion() {
  try {
    const entry = readFileSync(path.join(__dirname, 'public', 'pagefind', 'pagefind-entry.json'));
    return createHash('sha256').update(entry).digest('hex').slice(0, 12);
  } catch {
    return 'dev';
  }
}
const PAGEFIND_VERSION = pagefindVersion();

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  // Vercel 部署使用默认的服务端渲染模式
  images: {
    remotePatterns: [],
    formats: ['image/avif', 'image/webp'],
  },
  // 压缩
  compress: true,
  // 性能优化
  poweredByHeader: false,
  env: { NEXT_PUBLIC_PAGEFIND_VERSION: PAGEFIND_VERSION },
  // The client loads Pagefind from /pagefind/<version>/ (see lib/search/pagefindClient.ts); only the CURRENT
  // version is rewritten to the real files, so stale versions fall through to a normal (uncached) 404.
  async rewrites() {
    return {
      beforeFiles: [{ source: `/pagefind/${PAGEFIND_VERSION}/:path*`, destination: '/pagefind/:path*' }],
      afterFiles: [],
      fallback: [],
    };
  },
  // 安全headers
  async headers() {
    return [
      {
        source: '/:path*',
        headers: [
          {
            key: 'X-DNS-Prefetch-Control',
            value: 'on',
          },
          {
            key: 'X-Frame-Options',
            value: 'SAMEORIGIN',
          },
          {
            key: 'X-Content-Type-Options',
            value: 'nosniff',
          },
          {
            key: 'Referrer-Policy',
            value: 'origin-when-cross-origin',
          },
        ],
      },
      // Cache policy for static search/data assets (see PR description):
      // - Pagefind fragments/indexes/meta have content hashes in their file names → immutable, but ONLY under the
      //   current /pagefind/<version>/ prefix. Header rules match by path, not by file existence, so an
      //   unscoped rule also made 404s for stale/nonexistent hashes immutable (a rollback that restores those
      //   hashes would then stay broken in browsers for a year). Within one version the file set is fixed (the
      //   version is a hash of pagefind-entry.json), so a miss there can never turn into a hit later.
      {
        source: `/pagefind/${PAGEFIND_VERSION}/:dir(fragment|index)/:file*`,
        headers: [{ key: 'Cache-Control', value: 'public, max-age=31536000, immutable' }],
      },
      {
        source: `/pagefind/${PAGEFIND_VERSION}/:file(.*\\.pf_meta)`,
        headers: [{ key: 'Cache-Control', value: 'public, max-age=31536000, immutable' }],
      },
      // - pagefind.js / pagefind-entry.json / wasm.*.pagefind etc. keep fixed names but point at the hashed files, so a
      //   stale copy only matters briefly: short max-age + background revalidation.
      {
        source: '/pagefind/:prefix*/:file(pagefind[^.]*\\.(?:js|json|css)|wasm\\..*)',
        headers: [{ key: 'Cache-Control', value: 'public, max-age=3600, stale-while-revalidate=86400' }],
      },
      // - /data/*.json have unversioned names (Bible text rarely changes, presets change with deploys):
      //   1 day fresh, then served stale for up to a week while revalidating.
      {
        source: '/data/:file*',
        headers: [{ key: 'Cache-Control', value: 'public, max-age=86400, stale-while-revalidate=604800' }],
      },
      {
        source: '/api/:path*',
        headers: [
          {
            key: 'X-Robots-Tag',
            value: 'noindex, nofollow',
          },
        ],
      },
    ];
  },
};

module.exports = nextConfig;
